CREATE TABLE "Caregiver" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "carepartner_id" integer,
  "name" text,
  "role" text
);

CREATE TABLE "Carepartner" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "name" text
);

CREATE TABLE "Module" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "module_type" text,
  "caregiver_id" integer,
  "carepartner_id" integer,
  "metadata_id" integer
);

CREATE TABLE "Configuration" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "carepartner_id" integer,
  "module_id" integer,
  "occurence_type" text,
  "occurence_definition" text[],
  "position" integer,
  PRIMARY KEY ("carepartner_id", "position")
);

CREATE TABLE "Exception" (
  "configuration_id" integer,
  "exception_type" text,
  "exception_definition" text[]
);

CREATE TABLE "PhotoMedia" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "uri" text,
  "displayed_name" text,
  "filename" text,
  "extension" text
);

CREATE TABLE "VideoMedia" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "uri" text,
  "displayed_name" text,
  "filename" text,
  "extension" text
);

CREATE TABLE "AudioMedia" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "uri" text,
  "displayed_name" text,
  "filename" text,
  "extension" text
);

CREATE TABLE "WeatherWidget" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "zipcode" text
);

CREATE TABLE "NewsWidget" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "category" text,
  "language" text, 
  "country" text
);

CREATE TABLE "CarepartnerLocationPrompt" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "location" text,
  "message" text,
  "image_uri" text
);

CREATE TABLE "CaregiverLocationPrompt" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "location" text,
  "message" text,
  "image_uri" text
);

CREATE TABLE "MessagePrompt" (
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "message" text,
  "image_uri" text
);

CREATE TABLE "EventPrompt" (
  "list_id" integer,
  "id" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "time" time,
  "text" text
);

CREATE OR REPLACE PROCEDURE insert_configurations(
    p_carepartner_id INT,
    p_configs JSONB
)
LANGUAGE plpgsql
AS $$
DECLARE
    to_delete_row RECORD;
    new_row RECORD;
BEGIN
    CREATE TEMP TABLE tmp_configs AS
    SELECT
        (conf->>'id')::INT AS id,
        (conf->>'module_id')::INT AS module_id,
        conf->>'occurence_type' AS occurence_type,
        ARRAY(SELECT jsonb_array_elements_text(conf->'occurence_definition')) AS occurence_definition,
        (conf->>'position')::INT AS position
    FROM jsonb_array_elements(p_configs) AS conf;

    FOR to_delete_row IN SELECT * FROM tmp_configs ORDER BY position ASC LOOP
        IF to_delete_row.id IS NOT NULL THEN
            DELETE FROM "Configuration" WHERE id = to_delete_row.id;
            IF FOUND THEN
                UPDATE "Configuration" SET position = position - 1 WHERE carepartner_id = p_carepartner_id AND position > to_delete_row.position;
            END IF;
        END IF;
    END LOOP;

    FOR new_row IN SELECT * FROM tmp_configs ORDER BY position ASC LOOP
        UPDATE "Configuration"
        SET position = "Configuration".position + 1
        FROM (
            SELECT id, position
            FROM "Configuration"
            WHERE carepartner_id = p_carepartner_id
              AND position >= new_row.position
            ORDER BY position DESC
        ) desc_positions
        WHERE "Configuration".id = desc_positions.id;
        IF new_row.id IS NOT NULL THEN
            INSERT INTO "Configuration" (
                id,
                carepartner_id,
                module_id,
                occurence_type,
                occurence_definition,
                position
            ) VALUES (
                new_row.id,
                p_carepartner_id,
                new_row.module_id,
                new_row.occurence_type,
                new_row.occurence_definition,
                new_row.position
            );
        ELSE
            INSERT INTO "Configuration" (
                carepartner_id,
                module_id,
                occurence_type,
                occurence_definition,
                position
            ) VALUES (
                p_carepartner_id,
                new_row.module_id,
                new_row.occurence_type,
                new_row.occurence_definition,
                new_row.position
            );
        END IF;
    END LOOP;

    DROP TABLE tmp_configs;
END;
$$;

CREATE OR REPLACE PROCEDURE delete_configurations(
    p_carepartner_id INT,
    id_list INT[]
)
LANGUAGE plpgsql
AS $$
DECLARE
    current_id INT;
    pos INT;
BEGIN
    FOREACH current_id IN ARRAY id_list
    LOOP
        SELECT position INTO pos FROM "Configuration" WHERE id = current_id;
        DELETE FROM "Configuration" WHERE id = current_id;
        UPDATE "Configuration" SET position = position - 1 WHERE carepartner_id = p_carepartner_id AND position > pos;
    END LOOP;
END;
$$;